from pathlib import Path
from datetime import datetime,timezone
import json,hashlib,uuid,copy
T=Path(__file__).resolve().parent
def read(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def write(p,d):
 with Path(p).open('x',encoding='utf-8') as f:json.dump(d,f,ensure_ascii=False,indent=2)
mapping=read(T/'active-native-map.json');out=[]
for patch,instruction in [('p01_03','Remove ONLY the small red triangular fabric visible at bottom edge near x330..440,y1180..1254. This is not a separate flag. Keep the existing small gold ball and its square gold mounting cap near x300,y1100 exactly unchanged, then below the cap leave just one thin gold suspension cord continuing vertically out through bottom, against natural pale stone wall. No red cloth, flag, red pole, hanging banner panel, coin or medallion in this crop. The actual banner top is further BELOW this crop. All red/gold architecture above and stone joints must stay exactly the same.'),('p02_02','Remove ONLY the partial gold ring/coin/emblem visible at far right on the red hanging fabric near x1200..1254,y900..1000. Restore plain red fabric there. This cropped area of the approved banner is plain red; its gold coins start further below, outside this crop. Preserve the existing red top rod, gold finial, plaque, stone wall, banner gold vertical edge and everything else exactly. Do not add any coin, circular symbol, lettering or new ornament.')]:
 old=mapping[patch];prep=read(T/'records'/f'{old}.preparation.json');native=T/'native'/f'{old}.png';version=patch+'_v'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S')+'_'+uuid.uuid4().hex[:8];prefix=T/'records'/version
 prompt='Use case: precise-object-edit. Output one opaque native 1254 x 1254 square with EXACTLY the same framing and scale as the LAST reference image. Inputs 1/2/3 are style/layout references only; input4 LAST is the existing native edit target. '+instruction+' Preserve all native surrounding pixels and the top/left anchor strips. No blur, image resizing, reframing, new structure, labels or watermark.'
 refs=copy.deepcopy(prep['references'][:3])+[{'path':str(native),'sha256':sha(native),'dimensions':[1254,1254],'role':'LAST IMAGE: actual native edit target, change only named unwanted feature'}]
 req={'prompt':prompt,'referenced_image_paths':[r['path'] for r in refs],'transparent_background':False};rp=Path(str(prefix)+'.request.json');pp=Path(str(prefix)+'.prompt.txt');write(rp,req);pp.write_text(prompt,encoding='utf-8');write(Path(str(prefix)+'.reference-evidence.json'),refs)
 prep.update({'version':version,'preparedAt':datetime.now(timezone.utc).isoformat(),'request':str(rp),'requestSha256':sha(rp),'prompt':str(pp),'promptSha256':sha(pp),'references':refs,'status':'prepared_not_generated','nativeCorrectionOf':{'version':old,'path':str(native),'sha256':sha(native)},'localContent':instruction,'localContentEvidence':{'source':'direct native quick QA against approved local guide','priorPreparation':str(T/'records'/f'{old}.preparation.json'),'priorPreparationSha256':sha(T/'records'/f'{old}.preparation.json')},'actualModel':None,'actualQuality':None})
 write(Path(str(prefix)+'.preparation.json'),prep);out.append({'tile':T.name,'patch':patch,'version':version,'target':str(native),'request':str(rp)})
write(T/'records/native-corrections-wave3-20261013.json',{'corrections':out,'reason':'Do not propagate false flag triangle and premature coin from unreviewed halo. Existing originals retained.','formalAccepted':False});print(json.dumps(out))
